#version 450

// Mode determined by specialization constant:
//   mode 0: local workgroup Blelloch exclusive scan + per-group reduction
//   mode 1: global scan of per-group reductions (runs in one workgroup)
//   mode 2: add carry (per-group scan result) to each element
layout(constant_id=0) const uint mode = 0;

// Push constants
layout(push_constant, std430) uniform Push {
	uint n;              // valid element count
	uint workgroup_n;    // number of workgroups submitted (for padding handling)
};

// Buffers (binding sets are handled in Godot code):
//   binding 0: input array (int[])
//   binding 1: output array (exclusive scan result, int[])
//   binding 2: per-workgroup reductions/scans (int[])

layout(binding=0) buffer Input { int data[]; };
layout(binding=1) buffer Output { int out_data[]; };
layout(binding=2) buffer Groups { int groups[]; };

// Shared memory for Blelloch scan within a workgroup (max workgroup size 256)
shared int temp[256];

void main() {
	uint tid = gl_LocalInvocationID.x;
	uint wid = gl_WorkGroupID.x;

	if (mode == 0) {
		// --- mode 0: local Blelloch exclusive scan per workgroup ---
		uint offset = wid * 256u;
		// Pad out-of-bounds to 0 so they don't affect reduction
		int val = (offset + tid < n) ? data[offset + tid] : 0;
		temp[tid] = val;

		// Up-sweep (reduce)
		for (uint d = 256u >> 1u; d > 0u; d >>= 1u) {
			barrier();
			if (tid < d) {
				temp[tid + d] = temp[tid] + temp[tid + d];
			}
		}

		// Save the per-workgroup reduction total before zeroing
		barrier();
		if (tid == 0) {
			groups[wid] = temp[255];
			temp[255] = 0; // zero last element for exclusive scan
		}

		// Down-sweep
		for (uint d = 1u; d < 256u; d <<= 1u) {
			barrier();
			if (tid < d) {
				int t = temp[tid + d];
				temp[tid + d] = temp[tid] + t;
				temp[tid] = t;
			}
		}

		// Write exclusive scan result
		barrier();
		if (offset + tid < n) {
			out_data[offset + tid] = temp[tid];
		}

	} else if (mode == 1) {
		// --- mode 1: scan the workgroup totals (single workgroup) ---
		int val = (tid < workgroup_n) ? groups[tid] : 0;
		temp[tid] = val;

		// Up-sweep
		for (uint d = 256u >> 1u; d > 0u; d >>= 1u) {
			barrier();
			if (tid < d) {
				temp[tid + d] = temp[tid] + temp[tid + d];
			}
		}

		barrier();
		if (tid == 0) {
			temp[255] = 0;
		}

		// Down-sweep
		for (uint d = 1u; d < 256u; d <<= 1u) {
			barrier();
			if (tid < d) {
				int t = temp[tid + d];
				temp[tid + d] = temp[tid] + t;
				temp[tid] = t;
			}
		}

		barrier();
		if (tid < workgroup_n) {
			groups[tid] = temp[tid];
		}

	} else { // mode 2
		// --- mode 2: add carry (per-group scan result) back to each group ---
		uint offset = wid * 256u;
		if (offset + tid < n) {
			out_data[offset + tid] += groups[wid];
		}
	}
}

