extends Node

const INPUT_FILE = "res://data/input.txt"
const OUTPUT_FILE = "/home/user/scan/output/result.json"
const WG_SIZE = 256

func _ready():
	# Create a local compute-only RenderingDevice independent of window/surface.
	var rd = RenderingServer.create_local_rendering_device()
	if rd == null:
		printerr("No RenderingDevice available!")
		return
	_run_scan(rd)
	# The project terminates itself after writing the output.
	get_tree().quit()

func _run_scan(rd: RenderingDevice):
	# --- 1. Read input from the provided file ---
	var file = FileAccess.open(INPUT_FILE, FileAccess.READ)
	if file == null:
		printerr("Cannot open input file: " + INPUT_FILE)
		return
	var tokens := []
	var line = file.get_line()
	while line != null:
		for token in line.split(" ", false):
			tokens.append(int(token))
		line = file.get_line()
	file.close()

	if tokens.is_empty():
		printerr("No tokens read from input")
		return

	var n = tokens[0]
	var raw_data: PackedInt32Array = []
	for i in range(1, tokens.size()):
		raw_data.append(tokens[i])

	if raw_data.size() < n:
		printerr("Not enough data: declared %d but found %d" % [n, raw_data.size()])
		return

	# Pad input/output buffer to a multiple of workgroup size (WG_SIZE = 256).
	var padded_count = int(ceil(float(n) / WG_SIZE)) * WG_SIZE
	var workgroup_n = padded_count / WG_SIZE

	var input_data := raw_data.duplicate()
	input_data.resize(padded_count) # new padded slots init to 0

	# Upload data to GPU storage buffers.
	var input_buf = _make_buffer(rd, input_data)
	var output_buf = rd.storage_buffer_create(input_data.size() * 4, PackedByteArray())
	var groups_buf = rd.storage_buffer_create(workgroup_n * 4, PackedByteArray())

	# --- 2. Build the GPU compute pipeline ---
	var shader = _compile_shader(rd)
	var pipeline = rd.compute_pipeline_create(shader)

	var uniform_0 = RDUniform.new()
	uniform_0.uniform_type = RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER
	uniform_0.binding = 0
	uniform_0.add_id(input_buf)
	var uniform_1 = RDUniform.new()
	uniform_1.uniform_type = RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER
	uniform_1.binding = 1
	uniform_1.add_id(output_buf)
	var uniform_2 = RDUniform.new()
	uniform_2.uniform_type = RenderingDevice.UNIFORM_TYPE_STORAGE_BUFFER
	uniform_2.binding = 2
	uniform_2.add_id(groups_buf)
	var uniform_set = rd.uniform_set_create([uniform_0, uniform_1, uniform_2], shader, 0)

	# --- 3. Dispatch the compute shader (three passes) ---
	# Mode 0: local Blelloch exclusive scan per workgroup -> writes each group's reduction to groups_buf.
	_dispatch(rd, pipeline, uniform_set, n, workgroup_n, 0)
	# Mode 1: scan the per-workgroup reductions (single workgroup) -> total sum ends up at the last element.
	_dispatch(rd, pipeline, uniform_set, n, workgroup_n, 1)
	# Mode 2: add each group's scanned prefix (carry) back to its output elements.
	_dispatch(rd, pipeline, uniform_set, n, workgroup_n, 2)

	# --- 4. Read back the results ---
	var raw_groups = rd.buffer_get_data(groups_buf)
	var groups_ints = raw_groups.to_int32_array()
	var total = groups_ints[workgroup_n - 1]

	var raw_out = rd.buffer_get_data(output_buf)
	var out_ints = raw_out.to_int32_array()
	var prefix_sum: PackedInt32Array = []
	for i in range(n):
		prefix_sum.append(out_ints[i])

	# Cleanup RIDs (note: destroying the device below frees them too, but be explicit).
	rd.free_rid(input_buf)
	rd.free_rid(output_buf)
	rd.free_rid(groups_buf)
	rd.free_rid(uniform_set)
	rd.free_rid(pipeline)
	rd.free_rid(shader)
	rd.free_rid(rd) # free the device itself

	# --- 5. Write the output JSON file ---
	var out_dir = OUTPUT_FILE.get_base_dir()
	if not DirAccess.dir_exists_absolute(out_dir):
		DirAccess.make_dir_recursive_absolute(out_dir)
	var result = {
		"count": n,
		"total": total,
		"prefix_sum": Array(prefix_sum)
	}
	var json = JSON.stringify(result)
	var outf = FileAccess.open(OUTPUT_FILE, FileAccess.WRITE)
	if outf != null:
		outf.store_string(json)
		outf.close()
	print("Done: N=%d, total=%d" % [n, total])

func _make_buffer(rd: RenderingDevice, ints: PackedInt32Array) -> RID:
	var b := PackedByteArray()
	b.resize(ints.size() * 4)
	for i in ints.size():
		b.encode_s32(i * 4, ints[i])
	return rd.storage_buffer_create(b.size(), b)

func _dispatch(rd, pipeline, uniform_set, n, workgroup_n, mode):
	var pc := PackedByteArray()
	pc.resize(12)
	pc.encode_u32(0, n)
	pc.encode_u32(4, workgroup_n)
	pc.encode_u32(8, mode)
	var list = rd.compute_list_begin()
	rd.compute_list_bind_compute_pipeline(list, pipeline)
	rd.compute_list_bind_uniform_set(list, uniform_set, 0)
	rd.compute_list_set_push_constant(list, pc, pc.size())
	var x = workgroup_n if mode == 0 or mode == 2 else 1
	rd.compute_list_dispatch(list, x, 1, 1)
	rd.compute_list_end()
	rd.submit()
	rd.sync()

func _compile_shader(rd) -> RID:
	var src = RDShaderSource.new()
	src.source_compute = FileAccess.get_file_as_string("res://shaders/scan.glsl")
	var spirv = rd.shader_compile_spirv_from_source(src)
	if spirv.compile_error_compute != "":
		printerr("Shader error:\n" + spirv.compile_error_compute)
	return rd.shader_create_from_spirv(spirv)
